package vn.com.apartment.billing;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="payment_qr_allocations") public class PaymentQrAllocation{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="payment_qr_request_id") private PaymentQrRequest qrRequest;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="receivable_item_id") private ReceivableItem receivableItem;@Column(nullable=false,precision=18,scale=2) private BigDecimal amount;protected PaymentQrAllocation(){}PaymentQrAllocation(PaymentQrRequest qr,ReceivableItem item,BigDecimal amount){qrRequest=qr;receivableItem=item;this.amount=amount;}public ReceivableItem getReceivableItem(){return receivableItem;}public BigDecimal getAmount(){return amount;}}
